package io.dndroll.backup;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.util.*;import java.sql.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
class CampaignEvidenceGraphIT {
 @TempDir Path root;
 @Test void auditsScopedGraphWithoutMutationAndNeverClaimsRestore()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){var before=f.snapshot();var report=CampaignEvidenceGraphCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign);assertEquals("BLOCKED",report.status());assertFalse(report.executable());assertTrue(report.consistent());assertEquals(before,f.snapshot());assertFalse(report.toString().contains("PRIVATE_AUDIT"));assertThrows(java.io.IOException.class,()->CampaignEvidenceGraphCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,UUID.randomUUID()));}}
 @Test void malformedSelectedJsonBlocksButOtherCampaignDoesNotEnterGraph()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){UUID other=UUID.randomUUID();f.jdbc.update("insert into campaign(id,name) values (?,'PRIVATE_OTHER')",other);f.jdbc.update("insert into character_card(id,campaign_id,sheet) values (?,?,'{\"private\":\"SECRET\"}')",UUID.randomUUID(),other);Path archive=root.resolve("with-other.zip");new PostgresBackup(new DriverManagerDataSource(f.url,f.username,f.password),f.assets.toString(),RecoveryAuditIT.required("BACKUP_PG_DUMP"),f.url,f.username,f.password).create(Files.createDirectory(root.resolve("other-work")),archive);assertTrue(CampaignEvidenceGraphCommand.inspect(archive,f.url,f.username,f.password,f.assets,f.campaign).consistent());assertThrows(java.io.IOException.class,()->CampaignEvidenceGraphCommand.inspect(archive,f.url,f.username,f.password,f.assets,other));}}
 @Test void changedArchiveAndUnknownColumnsFailBeforeGraph()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){f.jdbc.update("update campaign set name='changed' where id=?",f.campaign);assertThrows(java.io.IOException.class,()->CampaignEvidenceGraphCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign));f.jdbc.execute("alter table stabilization_state add column unknown_source jsonb");assertThrows(java.io.IOException.class,()->CampaignEvidenceGraphCommand.inspect(f.archive,f.url,f.username,f.password,f.assets,f.campaign));}}
 @Test void readsNonemptyTypedCardHistoryAndRejectsSqlJsonMismatch()throws Exception{var owner=new RecoveryAuditIT();owner.root=root;try(var f=owner.new Fixture()){UUID id=UUID.randomUUID();var json=tools.jackson.databind.json.JsonMapper.builder().build();var sheet=io.dndroll.domain.CharacterSheet.empty("PRIVATE_CARD");var card=new io.dndroll.application.CharacterService.Card(id,f.campaign,0,false,false,false,List.of(),sheet);f.jdbc.update("insert into character_card(id,campaign_id,version,sheet) values (?,?,0,?::jsonb)",id,f.campaign,json.writeValueAsString(sheet));f.jdbc.update("insert into character_history(character_id,version,actor,kind,reason,at,after_state) values (?,0,'PRIVATE_AUDIT_ACTOR','CREATE','PRIVATE_REASON',now(),?::jsonb)",id,json.writeValueAsString(card));Path archive=root.resolve("typed.zip");new PostgresBackup(new DriverManagerDataSource(f.url,f.username,f.password),f.assets.toString(),RecoveryAuditIT.required("BACKUP_PG_DUMP"),f.url,f.username,f.password).create(Files.createDirectory(root.resolve("typed-work")),archive);var before=f.snapshot();var p=CampaignEvidenceGraphCommand.inspect(archive,f.url,f.username,f.password,f.assets,f.campaign);assertTrue(p.consistent(),p.blockers().toString());assertFalse(p.edges().isEmpty());assertEquals(before,f.snapshot());f.jdbc.update("update character_history set after_state=jsonb_set(after_state,'{version}','9') where character_id=?",id);Path bad=root.resolve("bad-typed.zip");new PostgresBackup(new DriverManagerDataSource(f.url,f.username,f.password),f.assets.toString(),RecoveryAuditIT.required("BACKUP_PG_DUMP"),f.url,f.username,f.password).create(Files.createDirectory(root.resolve("bad-typed-work")),bad);p=CampaignEvidenceGraphCommand.inspect(bad,f.url,f.username,f.password,f.assets,f.campaign);assertFalse(p.consistent());assertTrue(p.blockers().contains("SQL_JSON_VERSION_MISMATCH"));}}
 @Test void swappedBeforeSnapshotsCannotBorrowAnotherHistoryRowsVersion()throws Exception{
  var owner=new RecoveryAuditIT();owner.root=root;
  try(var f=owner.new Fixture()){
   UUID id=UUID.randomUUID();var json=tools.jackson.databind.json.JsonMapper.builder().build();var sheet=io.dndroll.domain.CharacterSheet.empty("PRIVATE_CARD");
   var cards=new ArrayList<io.dndroll.application.CharacterService.Card>();
   for(long version=0;version<3;version++)cards.add(new io.dndroll.application.CharacterService.Card(id,f.campaign,version,false,false,false,List.of(),sheet));
   f.jdbc.update("insert into character_card(id,campaign_id,version,sheet) values (?,?,2,?::jsonb)",id,f.campaign,json.writeValueAsString(sheet));
   for(int version=0;version<3;version++)f.jdbc.update("insert into character_history(character_id,version,actor,kind,reason,at,before_state,after_state) values (?,?,'PRIVATE_AUDIT_ACTOR','EDIT','PRIVATE_REASON',now(),?::jsonb,?::jsonb)",id,version,version==0?null:json.writeValueAsString(cards.get(version==1?1:0)),json.writeValueAsString(cards.get(version)));
   try(var connection=DriverManager.getConnection(f.url,f.username,f.password)){
    var report=CampaignEvidenceGraph.inspect(f.campaign,CampaignEvidenceGraphCommand.read(connection,f.campaign));
    assertTrue(report.blockers().contains("SQL_JSON_VERSION_MISMATCH"));
   }
  }
 }
}
